function setup(){
  createCanvas(640, 640);
}

function draw(){
  background(0, 20, 35);
  translate(width/2, height/2);
  rotate(radians(frameCount));
  for(let i = 0; i < 360; i+=10){
    let x = sin(radians(i+frameCount));
    let y = cos(radians(i+frameCount));

    let x2 = x * sqrt(1 - pow(y, 2));
    let y2 = y * sqrt(1 - pow(x, 2));
    stroke(0, 255, 255);
    strokeWeight(1);
    line(x*150, y*150, x2*100, y2*100);
    strokeWeight(3);

    stroke(255, 150, 0);
    ellipse(x2*100, y2*100, 3, 3);
    ellipse(x*150, y*150, 5, 5);
  }
}
